SELECT quantity_bucket, latest_last_restock, avg_quantity FROM (SELECT CASE WHEN quantity >= 211 THEN 'high' WHEN quantity >= 34 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(last_restock) AS latest_last_restock, ROUND(AVG(quantity), 2) AS avg_quantity FROM inventory GROUP BY CASE WHEN quantity >= 211 THEN 'high' WHEN quantity >= 34 THEN 'mid' ELSE 'low' END) AS t WHERE avg_quantity > 58;
